<script setup>
import { computed, onMounted, ref } from 'vue'
import { ArrowRight, ArrowUpRight, Check, ChevronRight, Headphones, MapPin, Sparkles } from 'lucide-vue-next'
import { useRoute, useRouter } from 'vue-router'
import { helpArticles, resources } from '../mocks/data'
import { getPublicProducts, getPublicRegions } from '../api'
import PageIntro from '../components/PageIntro.vue'
import Footer from '../components/Footer.vue'
import ContactBand from '../components/ContactBand.vue'
import ProductDetail from '../components/ProductDetail.vue'
import BuyFlow from '../components/BuyFlow.vue'
import Checkout from '../components/Checkout.vue'
import ContentList from '../components/ContentList.vue'
import ArticlePage from '../components/ArticlePage.vue'
import AuthPanel from '../components/AuthPanel.vue'
const router = useRouter(); const route = useRoute(); const section = computed(() => route.meta.section || 'home'); const props = { get section() { return section.value } }; const selectedRegion = ref(''); const toast = ref(''); const products = ref([]); const regions = ref([]); const catalogError = ref(''); const product = computed(() => products.value.find((p) => p.slug === route.params.slug) || products.value[0] || {})
async function loadCatalog() { try { const [productResponse, regionResponse] = await Promise.all([getPublicProducts(), getPublicRegions()]); products.value = productResponse.data.map((item) => ({ ...item, slug: String(item.id), short: `#${item.id}`, summary: `${item.region} · ${item.product_type}`, scenes: item.product_type, platforms: item.region, delivery: item.is_in_stock ? '当前有货' : '暂时无货' })); regions.value = regionResponse.data.map((item) => item.name); selectedRegion.value = regions.value[0] || '' } catch (error) { catalogError.value = error.userMessage || '产品目录加载失败' } }
function go(path) { router.push(path) }
function choose(region) { selectedRegion.value = region; go('/buy?region=' + encodeURIComponent(region)) }
onMounted(loadCatalog)
</script>
