ection-head"><div><p class="eyebrow">ROUTES ACROSS MARKETS</p><h2>从你要去的地方开始。</h2></div><button class="outline-button" @click="go('/regions')">浏览地区 <ArrowUpRight :size="15" /></button></div><div class="region-line"><button v-for="r in regions" :key="r" @click="choose(r)"><MapPin :size="15" />{{ r }}<ArrowUpRight :size="13" /></button></div></section><section class="section light flow-section"><div class="flow-aside"><p class="eyebrow dark">A CLEAR DELIVERY FLOW</p><h2>选择不应该<br />从猜测开始。</h2><p>从地区、产品、周期到交付内容，每一步都可查看、可回退、可确认。</p><button class="button" @click="go('/buy')">开始选购 <ArrowUpRight :size="15" /></button></div><div class="flow-list"><div v-for="item in [['选择地区','按业务市场筛选线路','01'],['选择产品','匹配直播、短视频或社媒场景','02'],['确认交付','查看节点、订阅与二维码信息','03'],['提交订单','登录后继续，等待线路开通','04'] ]" :key="item[2]" class="flow-item"><span>{{ item[2] }}</span><div><h3>{{ item[0] }}</h3><p>{{ item[1] }}</p></div><ChevronRight :size="18" /></div></div></section><section class="section resource-band"><div><p class="eyebrow">LEARN BEFORE YOU CONNECT</p><h2>先把每一条线路用明白。</h2></div><div class="resource-links"><button @click="go('/help')"><Headphones :size="18" /><span>用户教程</span><small>Clash / V2Ray / NekoBox</small><ArrowUpRight :size="15" /></button><button @click="go('/resources')"><Sparkles :size="18" /><span>资源中心</span><small>出海网络与运营指南</small><ArrowUpRight :size="15" /></button></div></section><ContactBand /><Footer /></template>
  <template v-else-if="props.section === 'products'"><PageIntro title="产品服务" desc="为不同跨境业务场景准备的网络线路，交付内容清晰，选择路径简单。" /><section class="section light"><div class="product-grid product-grid-page"><article v-for="p in products" :key="p.id" class="product-card" @click="go('/products/' + p.slug)"><div class="card-top"><span class="product-index">{{ p.short }}</span><ArrowUpRight :size="18" /></div><h3>{{ p.name }}</h3><p>{{ p.summary }}</p><ul><li><Check :size="14" />{{ p.scenes }}</li><li><Check :size="14" />{{ p.platforms }}</li><li><Check :size="14" />{{ p.delivery }}</li></ul><div class="card-foot"><b>¥{{ p.price }}<small>/月起</small></b><span>查看详情 <ArrowRight :size="14" /></span></div></article></div></section><Footer /></template>
  <ProductDetail v-else-if="props.section === 'product-detail'" :product="product" />
  <BuyFlow v-else-if="props.section === 'regions' || props.section === 'buy'" />
  <Checkout v-else-if="props.section === 'checkout'" />
  <ContentList v-else-if="props.section === 'help'" title="用户教程" desc="从客户端安装到线路导入，按你使用的设备找到对应步骤。" :items="helpArticles" label="教程" />
  <ContentList v-else-if="props.section === 'resources'" title="资源中心" desc="围绕出海网络、直播、短视频和社媒运营的实用指南。" :items="resources" label="文章" />
  <ArticlePage v-else-if="props.section === 'article'" />
  <template v-else-if="props.section === 'about'"><PageIntro title="关于玖玖IP" desc="我们把跨境网络服务做成一条可以被看懂、被选择、被交付的业务链路。" /><section class="section light about-copy"><div><p class="eyebrow dark">THE 99IP APPROACH</p><h2>不是把节点藏起来，<br />而是把交付讲清楚。</h2></div><div><p>玖玖IP面向跨境团队提供直播、短视频、社媒线路和静态住宅 IP。官网负责选择，客户中心承接真实订单、线路和续费管理。</p><p>产品、地区、库存、价格和业务状态均由当前业务 API 返回；教程和资源文章仍使用本地内容数据。</p></div></section><Footer /></template>
  <template v-else-if="props.section === 'contact'"><ContactBand full /><Footer /></template><AuthPanel v-else-if="props.section === 'login' || props.section === 'register'" portal="customer" /><AuthPanel v-else-if="props.section === 'admin-login'" portal="admin" /><AuthPanel v-else-if="props.section === 'sales-login'" portal="sales" /><template v-else><PageIntro title="页面不存在" desc="你访问的页面可能已移动，返回首页继续浏览。" /><div class="center-action"><button class="button" @click="go('/')">返回首页 <ArrowRight :size="15" /></button></div><Footer /></template>
</template>
